"""Validate schemas generated by a real FastMCP server before submitting calls."""

from typing import Annotated

import pytest
from mcp.server.fastmcp import FastMCP
from mcp.shared.memory import create_connected_server_and_client_session
from pydantic import Field

from nanobot.agent.tools.mcp import MCPToolWrapper
from nanobot.agent.tools.registry import ToolRegistry, is_tool_error_result


@pytest.mark.parametrize("tool_name, valid, invalid", [
    ("amount", 4.02, 4.021),
    ("name", "北京", "123"),
])
async def test_fastmcp_decimal_and_unicode_constraints(tool_name, valid, invalid):
    server = FastMCP("schema-compatibility")
    calls = []

    @server.tool()
    def amount(value: Annotated[float, Field(multiple_of=0.01)]) -> str:
        calls.append(value)
        return f"accepted {value}"

    @server.tool()
    def name(value: Annotated[str, Field(pattern=r"^\p{L}+$")]) -> str:
        calls.append(value)
        return f"accepted {value}"

    async with create_connected_server_and_client_session(server._mcp_server) as client:
        definition = next(tool for tool in (await client.list_tools()).tools if tool.name == tool_name)
        direct = await client.call_tool(tool_name, {"value": valid})
        assert not direct.isError
        assert calls == [valid]
        registry = ToolRegistry()
        wrapper = MCPToolWrapper(client, "compatibility", definition)
        registry.register(wrapper)
        arguments = {"value": valid}

        result = await registry.execute(wrapper.name, arguments)

        assert result == f"accepted {valid}"
        assert arguments == {"value": valid}
        assert calls == [valid, valid]
        result = await registry.execute(wrapper.name, {"value": invalid})
        assert is_tool_error_result(result)
        assert "value:" in result
        assert calls == [valid, valid]
